/**
 * Every image slot on the site. Single source of truth for:
 *  - ImageSlot ids (typed), default aspect ratio and placeholder icon;
 *  - docs/IMAGE_PROMPTS.md (generated by scripts/image-prompts.ts).
 *
 * To add a real photo: save it as public/images/<id>.jpg (or .png/.webp) and rebuild.
 * Keep this file free of path-alias imports: it is also executed directly by Node.
 */

export type ImageKind = "hero" | "interior" | "equipment" | "portrait" | "people" | "service" | "case" | "video" | "og";

export interface ImageSpec {
  kind: ImageKind;
  /** "w:h" */
  aspect: string;
  /** Minimum source resolution */
  min: string;
  /** Where it is used */
  usedOn: string;
  /** What must be in the frame */
  subject: string;
  /** Mood and light */
  mood?: string;
  /** Ready-to-use English prompt; the shared style suffix is appended in the doc */
  prompt: string;
  /** Extra negative prompt on top of the shared one */
  negative?: string;
  /** Real photo only (no AI): before/after, real reviews */
  realOnly?: boolean;
}

