function build(): Record<string, ImageSpec> {
  const r: Record<string, ImageSpec> = {
    "hero-desktop": {
      kind: "hero",
      aspect: "16:9",
      min: "2880×1620",
      usedOn: "Головна → Hero (десктоп)",
      subject: "Light, airy treatment room with a patient in her thirties laughing with the doctor; big windows; lots of negative space on the left for floating glass cards",
      mood: MOOD_CLINIC,
      prompt:
        "Wide cinematic shot of a light airy premium dental clinic treatment room with floor-to-ceiling windows, a woman in her thirties sitting upright in a cream leather dental chair laughing naturally with a male dentist in a navy scrub top, minimal Scandinavian interior with oak and travertine, plants, generous negative space on the left third",
    },
    "hero-mobile": {
      kind: "hero",
      aspect: "4:5",
      min: "1440×1800",
      usedOn: "Головна → Hero (мобільний)",
      subject: "Same scene as hero-desktop, vertical crop: patient and doctor centred, window light",
      mood: MOOD_CLINIC,
      prompt:
        "Vertical portrait composition in a light premium dental clinic, a woman in her thirties in a cream dental chair laughing with a dentist in a navy scrub top, window light from the side, minimal oak and travertine interior, calm and warm",
    },
    "hero-video-poster": {
      kind: "video",
      aspect: "16:9",
      min: "1920×1080",
      usedOn: "Головна → Hero-відео (опційно, постер)",
      subject: "First frame of a silent 10–15 s loop: slow dolly through the clinic corridor into the treatment room",
      mood: MOOD_CLINIC,
      prompt:
        "Slow cinematic dolly shot first frame through a bright minimalist dental clinic corridor with oak panels and soft daylight leading into a treatment room",
    },

    "people-consultation": {
      kind: "people",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Головна → Перший візит; Перший візит → hero",
      subject: "Doctor explaining a 3D treatment plan on a large screen to a couple, relaxed seating (not in the chair)",
      mood: MOOD_CLINIC,
      prompt:
        "A dentist sitting at a round table with a middle-aged couple explaining a 3D treatment plan on a large screen, relaxed consultation room with sofa-like chairs, coffee cups, natural daylight",
    },
    "people-calm-patient": {
      kind: "people",
      aspect: "4:5",
      min: "1800×2250",
      usedOn: "Головна → блок «Боїтеся?»; Лікування уві сні",
      subject: "Woman in her forties relaxed in the chair with headphones and a blanket; dim warm light; hand resting calmly",
      mood: "Low-key warm light, dark soft background (used in a dark section)",
      prompt:
        "A woman in her forties resting calmly in a dental chair with wireless headphones and a soft knit blanket, eyes closed, gentle smile, dim warm lighting, dark soft background, sense of safety",
    },
    "people-final-cta": {
      kind: "people",
      aspect: "16:9",
      min: "2880×1620",
      usedOn: "Головна → фінальний CTA (фон під склом)",
      subject: "Blurred-friendly background: reception with warm light, receptionist smiling, lots of calm space",
      mood: MOOD_CLINIC,
      prompt:
        "A warm premium dental clinic reception with a smiling receptionist behind a travertine desk, soft daylight, plants, calm and welcoming, generous negative space, slightly defocused",
    },
    "team-group": {
      kind: "people",
      aspect: "16:9",
      min: "2880×1620",
      usedOn: "Про клініку → Команда; Лікарі → hero",
      subject: "Whole team (9 doctors + assistants) standing naturally in the clinic lobby",
      mood: MOOD_CLINIC,
      prompt:
        "Group photo of a friendly dental clinic team of twelve people in coordinated navy, teal and white scrubs standing naturally in a bright minimalist lobby, relaxed smiles, editorial style",
    },

    "interior-reception": {
      kind: "interior",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Про клініку → Інтер'єр",
      subject: "Reception desk and waiting lounge",
      mood: MOOD_CLINIC,
      prompt: "Premium dental clinic reception with a curved travertine desk, oak slat wall, designer lounge chairs, plants, soft daylight, no people",
    },
    "interior-cabinet": {
      kind: "interior",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Про клініку → Інтер'єр; Технології",
      subject: "Treatment room: chair, microscope, big window",
      mood: MOOD_CLINIC,
      prompt: "Minimalist premium dental treatment room with a cream dental chair, white operating microscope, large window with greenery outside, warm oak cabinetry, no people",
    },
    "interior-lounge": {
      kind: "interior",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Про клініку → Інтер'єр",
      subject: "Waiting lounge with coffee station",
      mood: MOOD_CLINIC,
      prompt: "Cozy waiting lounge in a premium clinic with boucle armchairs, coffee station, magazines, warm lamp and daylight, calm atmosphere, no people",
    },
    "interior-kids": {
      kind: "interior",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Дитяча стоматологія; Про клініку",
      subject: "Kids' treatment room: tasteful, playful but not garish",
      mood: MOOD_CLINIC,
      prompt: "A tasteful kids' dental room with a pastel dental chair, a ceiling mural of soft clouds, wooden toys on a shelf, bright and calm, no people",
    },
    "interior-entrance": {
      kind: "interior",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Контакти → «Як знайти вхід»",
      subject: "REAL PHOTO recommended: the actual building entrance with the NaDent sign",
      mood: "Daylight, straight-on, entrance clearly recognisable",
      prompt: "Modern clinic entrance with glass doors and a minimal illuminated sign, clean facade, daylight, street-level view",
    },
    "interior-sterilization": {
      kind: "interior",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Головна → Стерильність; Про клініку → Стерилізація",
      subject: "Sterilization room with autoclave and sealed pouches",
      mood: MOOD_CLINIC,
      prompt: tech.sterilization[1],
    },
    "people-kids": {
      kind: "people",
      aspect: "4:5",
      min: "1800×2250",
      usedOn: "Головна → картка «Для дитини»",
      subject: "Child brushing teeth / laughing in the kids' room",
      mood: MOOD_CLINIC,
      prompt: "A laughing five-year-old boy holding an oversized toothbrush in a bright kids' dental room, playful, soft daylight",
    },
    "doctor-video-poster": {
      kind: "video",
      aspect: "16:9",
      min: "1920×1080",
      usedOn: "Сторінка лікаря → відео-знайомство (спільний постер, поки немає окремих)",
      subject: "Doctor sitting in the consultation room, looking at the camera, mid-sentence",
      mood: MOOD_CLINIC,
      prompt: "A dentist sitting in a bright consultation room speaking to the camera in a friendly way, interview framing, soft daylight, shallow depth of field",
    },
    "og-default": {
      kind: "og",
      aspect: "1200:630",
      min: "1200×630",
      usedOn: "Open Graph за замовчуванням (генерується автоматично, фото — опційний фон)",
      subject: "Calm clinic interior with space for the logo and a headline on the left",
      mood: MOOD_CLINIC,
      prompt: "Bright premium dental clinic interior, wide shot with generous empty space on the left for text, soft daylight, calm",
    },
  };

  for (const [id, s] of Object.entries(services)) {
    r[`service-${id}`] = {
      kind: "service",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: `Послуга «${id}» → hero, картки послуг, bento на головній`,
      subject: `${s.subject}. Keep the subject centred with generous margins: the image is cropped to 4:5 and 16:10.`,
      mood: MOOD_CLINIC,
      prompt: s.prompt,
    };
  }

  for (const [id, [subject, prompt]] of Object.entries(tech)) {
    r[`tech-${id}`] = {
      kind: "equipment",
      aspect: "4:3",
      min: "2400×1800",
      usedOn: "Головна → Технології; /tekhnolohii; сторінки послуг",
      subject,
      mood: MOOD_CLINIC,
      prompt,
    };
  }

  for (const [slug, look] of Object.entries(doctors)) {
    r[`doctor-${slug}`] = {
      kind: "portrait",
      aspect: "4:5",
      min: "1600×2000",
      usedOn: `Лікарі; /likari/${slug}; сторінки послуг. REAL PHOTO strongly preferred.`,
      subject: `Waist-up portrait of ${look}, arms relaxed, looking at the camera, same backdrop and light for the whole team`,
      mood: MOOD_PORTRAIT,
      prompt: `Waist-up editorial portrait of ${look}, relaxed confident posture, genuine closed-mouth smile, looking at the camera`,
    };
  }

  for (const [id, title] of Object.entries(cases)) {
    for (const phase of ["before", "after"] as const) {
      r[`case-${id}-${phase}`] = {
        kind: "case",
        aspect: "4:3",
        min: "1600×1200",
        usedOn: `До / після → ${title}`,
        subject: `${phase === "before" ? "BEFORE" : "AFTER"} treatment intraoral / smile photo, identical framing, light and white balance for both shots`,
        prompt: "— (AI generation is not allowed: use real clinical photos with the patient's written consent)",
        realOnly: true,
      };
    }
  }

  for (const n of [1, 2, 3]) {
    r[`review-video-${n}`] = {
      kind: "video",
      aspect: "9:16",
      min: "1080×1920",
      usedOn: "Головна → Відгуки; /vidhuky (постер відео-відгуку)",
      subject: "Frame from a real patient's video testimonial",
      prompt: "— (real patients only, with written consent)",
      realOnly: true,
    };
  }

  for (const [id, prompt] of Object.entries(articles)) {
    r[`blog-${id}`] = {
      kind: "service",
      aspect: "16:10",
      min: "2400×1500",
      usedOn: `Блог → обкладинка статті «${id}»`,
      subject: prompt,
      mood: MOOD_CLINIC,
      prompt,
    };
  }

  for (const [id, prompt] of Object.entries({
    "hygiene-whitening": "Flat lay of a toothbrush, floss and a whitening shade guide on a sand-coloured surface, fresh and bright",
    "implant-consult": "Titanium implant model and a printed CT scan on a light oak desk in a consultation room",
    "family-checkup": "A parent and child brushing teeth together in front of a bathroom mirror, morning light, playful",
  })) {
    r[`offer-${id}`] = {
      kind: "service",
      aspect: "16:10",
      min: "2000×1250",
      usedOn: `Акції → «${id}»`,
      subject: prompt,
      mood: MOOD_CLINIC,
      prompt,
    };
  }

  return r;
}

export const imageRegistry = build() as Record<ImageId, ImageSpec>;

type ServiceImage = `service-${keyof typeof services}`;
type TechImage = `tech-${keyof typeof tech}`;
type DoctorImage = `doctor-${keyof typeof doctors}`;
type CaseImage = `case-${keyof typeof cases}-${"before" | "after"}`;
type ArticleImage = `blog-${keyof typeof articles}`;

export type ImageId =
  | "hero-desktop"
  | "hero-mobile"
  | "hero-video-poster"
  | "people-consultation"
  | "people-calm-patient"
  | "people-final-cta"
  | "people-kids"
  | "team-group"
  | "interior-reception"
  | "interior-cabinet"
  | "interior-lounge"
  | "interior-kids"
  | "interior-entrance"
  | "interior-sterilization"
  | "doctor-video-poster"
  | "og-default"
  | `review-video-${1 | 2 | 3}`
  | `offer-${"hygiene-whitening" | "implant-consult" | "family-checkup"}`
  | ServiceImage
  | TechImage
  | DoctorImage
  | CaseImage
  | ArticleImage;

