export const SHARED_NEGATIVE =
  "overly white teeth, veneers look, plastic skin, cartoon, 3D render, clipart tooth, blue gloves close-up, blood, needles close-up, syringe, horror, dental tools in mouth close-up, distorted hands, extra fingers, text, watermark, logo, oversaturated, harsh flash, cold hospital lighting, stock-photo cheesiness";
